-- ============================================================================
-- ReadyPI OAuth Support Migration
-- ============================================================================
-- Migration: 001_add_oauth_support.sql
-- Date: 2026-05-06
-- Purpose: Add OAuth authentication support to ReadyPI
-- 
-- This migration:
-- 1. Ensures OAuth columns exist in users table
-- 2. Creates OAuth session tracking table
-- 3. Adds indexes for OAuth lookups
-- 4. Creates functions for OAuth user management
-- 5. Adds audit logging for OAuth events
-- ============================================================================

BEGIN;

-- ============================================================================
-- STEP 1: Verify and Update Users Table for OAuth
-- ============================================================================

-- Check if columns exist, add if missing
DO $$\nBEGIN\n    -- Add avatar_url if it doesn't exist\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.columns \n        WHERE table_name = 'users' AND column_name = 'avatar_url'\n    ) THEN\n        ALTER TABLE users ADD COLUMN avatar_url TEXT;\n        RAISE NOTICE 'Added avatar_url column to users table';\n    END IF;\n\n    -- Add oauth_provider if it doesn't exist\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.columns \n        WHERE table_name = 'users' AND column_name = 'oauth_provider'\n    ) THEN\n        ALTER TABLE users ADD COLUMN oauth_provider VARCHAR(50);\n        RAISE NOTICE 'Added oauth_provider column to users table';\n    END IF;\n\n    -- Add oauth_uid if it doesn't exist\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.columns \n        WHERE table_name = 'users' AND column_name = 'oauth_uid'\n    ) THEN\n        ALTER TABLE users ADD COLUMN oauth_uid VARCHAR(255);\n        RAISE NOTICE 'Added oauth_uid column to users table';\n    END IF;\n\n    -- Add last_login if it doesn't exist\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.columns \n        WHERE table_name = 'users' AND column_name = 'last_login'\n    ) THEN\n        ALTER TABLE users ADD COLUMN last_login TIMESTAMP;\n        RAISE NOTICE 'Added last_login column to users table';\n    END IF;\n\n    -- Make password_hash nullable for OAuth users\n    IF EXISTS (\n        SELECT 1 FROM information_schema.columns \n        WHERE table_name = 'users' AND column_name = 'password_hash' \n        AND is_nullable = 'NO'\n    ) THEN\n        ALTER TABLE users ALTER COLUMN password_hash DROP NOT NULL;\n        RAISE NOTICE 'Made password_hash nullable for OAuth users';\n    END IF;\nEND $$;\n\n-- ============================================================================\n-- STEP 2: Create OAuth Sessions Table\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS oauth_sessions (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n    provider VARCHAR(50) NOT NULL, -- google, github, etc.\n    provider_account_id VARCHAR(255) NOT NULL, -- Provider's user ID\n    access_token TEXT, -- OAuth access token (encrypted in production)\n    refresh_token TEXT, -- OAuth refresh token (encrypted in production)\n    token_expires_at TIMESTAMP, -- When the access token expires\n    scope TEXT, -- Requested OAuth scopes\n    id_token TEXT, -- Firebase ID token (for verification)\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    last_used_at TIMESTAMP,\n    is_active BOOLEAN DEFAULT TRUE,\n    CONSTRAINT unique_provider_account UNIQUE(provider, provider_account_id),\n    CONSTRAINT valid_provider CHECK (provider IN ('google', 'github', 'firebase'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_oauth_sessions_user_id ON oauth_sessions(user_id);\nCREATE INDEX IF NOT EXISTS idx_oauth_sessions_provider ON oauth_sessions(provider);\nCREATE INDEX IF NOT EXISTS idx_oauth_sessions_provider_account ON oauth_sessions(provider, provider_account_id);\nCREATE INDEX IF NOT EXISTS idx_oauth_sessions_is_active ON oauth_sessions(is_active);\n\nRAISE NOTICE 'Created oauth_sessions table';\n\n-- ============================================================================\n-- STEP 3: Create OAuth Audit Log Table\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS oauth_audit_logs (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    user_id UUID REFERENCES users(id) ON DELETE SET NULL,\n    event_type VARCHAR(50) NOT NULL, -- login, signup, token_refresh, logout, error\n    provider VARCHAR(50), -- google, github, firebase\n    status VARCHAR(50) NOT NULL, -- success, failure\n    error_message TEXT,\n    ip_address INET,\n    user_agent TEXT,\n    metadata JSONB, -- Additional context\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    CONSTRAINT valid_event_type CHECK (event_type IN ('login', 'signup', 'token_refresh', 'logout', 'error', 'token_exchange'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_oauth_audit_user_id ON oauth_audit_logs(user_id);\nCREATE INDEX IF NOT EXISTS idx_oauth_audit_event_type ON oauth_audit_logs(event_type);\nCREATE INDEX IF NOT EXISTS idx_oauth_audit_provider ON oauth_audit_logs(provider);\nCREATE INDEX IF NOT EXISTS idx_oauth_audit_status ON oauth_audit_logs(status);\nCREATE INDEX IF NOT EXISTS idx_oauth_audit_created_at ON oauth_audit_logs(created_at DESC);\n\nRAISE NOTICE 'Created oauth_audit_logs table';\n\n-- ============================================================================\n-- STEP 4: Add Unique Index for OAuth Provider + UID\n-- ============================================================================\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_users_oauth_provider_uid \nON users(oauth_provider, oauth_uid) \nWHERE oauth_provider IS NOT NULL;\n\nRAISE NOTICE 'Created unique index for oauth_provider + oauth_uid';\n\n-- ============================================================================\n-- STEP 5: Create Function to Update Last Login\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION update_user_last_login(p_user_id UUID)\nRETURNS VOID AS $$\nBEGIN\n    UPDATE users \n    SET last_login = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP\n    WHERE id = p_user_id;\nEND;\n$$ LANGUAGE plpgsql;\n\nRAISE NOTICE 'Created update_user_last_login function';\n\n-- ============================================================================\n-- STEP 6: Create Function to Log OAuth Events\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION log_oauth_event(\n    p_user_id UUID,\n    p_event_type VARCHAR,\n    p_provider VARCHAR,\n    p_status VARCHAR,\n    p_error_message TEXT DEFAULT NULL,\n    p_ip_address INET DEFAULT NULL,\n    p_user_agent TEXT DEFAULT NULL,\n    p_metadata JSONB DEFAULT NULL\n)\nRETURNS UUID AS $$\nDECLARE\n    v_log_id UUID;\nBEGIN\n    INSERT INTO oauth_audit_logs (\n        user_id, event_type, provider, status, error_message, \n        ip_address, user_agent, metadata\n    ) VALUES (\n        p_user_id, p_event_type, p_provider, p_status, p_error_message,\n        p_ip_address, p_user_agent, p_metadata\n    )\n    RETURNING id INTO v_log_id;\n    \n    RETURN v_log_id;\nEND;\n$$ LANGUAGE plpgsql;\n\nRAISE NOTICE 'Created log_oauth_event function';\n\n-- ============================================================================\n-- STEP 7: Create Function to Find or Create OAuth User\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION find_or_create_oauth_user(\n    p_email VARCHAR,\n    p_provider VARCHAR,\n    p_provider_uid VARCHAR,\n    p_full_name VARCHAR DEFAULT NULL,\n    p_avatar_url TEXT DEFAULT NULL\n)\nRETURNS TABLE(user_id UUID, is_new BOOLEAN) AS $$\nDECLARE\n    v_user_id UUID;\n    v_is_new BOOLEAN := FALSE;\nBEGIN\n    -- Try to find existing user by OAuth provider + UID\n    SELECT id INTO v_user_id FROM users \n    WHERE oauth_provider = p_provider AND oauth_uid = p_provider_uid;\n    \n    IF v_user_id IS NOT NULL THEN\n        -- User exists, update last login\n        PERFORM update_user_last_login(v_user_id);\n        RETURN QUERY SELECT v_user_id, FALSE;\n        RETURN;\n    END IF;\n    \n    -- Try to find existing user by email\n    SELECT id INTO v_user_id FROM users WHERE email = LOWER(p_email);\n    \n    IF v_user_id IS NOT NULL THEN\n        -- User exists, link OAuth provider\n        UPDATE users SET \n            oauth_provider = p_provider,\n            oauth_uid = p_provider_uid,\n            avatar_url = COALESCE(p_avatar_url, avatar_url),\n            full_name = COALESCE(p_full_name, full_name),\n            email_verified = TRUE,\n            last_login = CURRENT_TIMESTAMP,\n            updated_at = CURRENT_TIMESTAMP\n        WHERE id = v_user_id;\n        \n        RETURN QUERY SELECT v_user_id, FALSE;\n        RETURN;\n    END IF;\n    \n    -- Create new user\n    INSERT INTO users (\n        email, full_name, avatar_url, oauth_provider, oauth_uid, \n        email_verified, plan_tier, is_active\n    ) VALUES (\n        LOWER(p_email), p_full_name, p_avatar_url, p_provider, p_provider_uid,\n        TRUE, 'free', TRUE\n    )\n    RETURNING id INTO v_user_id;\n    \n    v_is_new := TRUE;\n    \n    RETURN QUERY SELECT v_user_id, v_is_new;\nEND;\n$$ LANGUAGE plpgsql;\n\nRAISE NOTICE 'Created find_or_create_oauth_user function';\n\n-- ============================================================================\n-- STEP 8: Create Function to Store OAuth Session\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION store_oauth_session(\n    p_user_id UUID,\n    p_provider VARCHAR,\n    p_provider_account_id VARCHAR,\n    p_access_token TEXT DEFAULT NULL,\n    p_refresh_token TEXT DEFAULT NULL,\n    p_token_expires_at TIMESTAMP DEFAULT NULL,\n    p_scope TEXT DEFAULT NULL,\n    p_id_token TEXT DEFAULT NULL\n)\nRETURNS UUID AS $$\nDECLARE\n    v_session_id UUID;\nBEGIN\n    INSERT INTO oauth_sessions (\n        user_id, provider, provider_account_id, access_token, refresh_token,\n        token_expires_at, scope, id_token, is_active\n    ) VALUES (\n        p_user_id, p_provider, p_provider_account_id, p_access_token, p_refresh_token,\n        p_token_expires_at, p_scope, p_id_token, TRUE\n    )\n    ON CONFLICT (provider, provider_account_id) DO UPDATE SET\n        access_token = EXCLUDED.access_token,\n        refresh_token = EXCLUDED.refresh_token,\n        token_expires_at = EXCLUDED.token_expires_at,\n        scope = EXCLUDED.scope,\n        id_token = EXCLUDED.id_token,\n        updated_at = CURRENT_TIMESTAMP,\n        last_used_at = CURRENT_TIMESTAMP\n    RETURNING id INTO v_session_id;\n    \n    RETURN v_session_id;\nEND;\n$$ LANGUAGE plpgsql;\n\nRAISE NOTICE 'Created store_oauth_session function';\n\n-- ============================================================================\n-- STEP 9: Create Trigger to Update OAuth Session Last Used\n-- ============================================================================\n\nCREATE OR REPLACE FUNCTION update_oauth_session_last_used()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.last_used_at = CURRENT_TIMESTAMP;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS update_oauth_sessions_last_used ON oauth_sessions;\nCREATE TRIGGER update_oauth_sessions_last_used\nBEFORE UPDATE ON oauth_sessions\nFOR EACH ROW\nEXECUTE FUNCTION update_oauth_session_last_used();\n\nRAISE NOTICE 'Created trigger for oauth_sessions last_used update';\n\n-- ============================================================================\n-- STEP 10: Create View for Active OAuth Sessions\n-- ============================================================================\n\nCREATE OR REPLACE VIEW active_oauth_sessions AS\nSELECT \n    os.id,\n    os.user_id,\n    u.email,\n    u.full_name,\n    os.provider,\n    os.provider_account_id,\n    os.token_expires_at,\n    os.created_at,\n    os.last_used_at,\n    CASE \n        WHEN os.token_expires_at IS NULL THEN 'never'\n        WHEN os.token_expires_at < CURRENT_TIMESTAMP THEN 'expired'\n        ELSE 'valid'\n    END AS token_status\nFROM oauth_sessions os\nJOIN users u ON os.user_id = u.id\nWHERE os.is_active = TRUE;\n\nRAISE NOTICE 'Created active_oauth_sessions view';\n\n-- ============================================================================\n-- STEP 11: Create View for OAuth Statistics\n-- ============================================================================\n\nCREATE OR REPLACE VIEW oauth_statistics AS\nSELECT \n    DATE(created_at) AS date,\n    event_type,\n    provider,\n    status,\n    COUNT(*) AS event_count\nFROM oauth_audit_logs\nWHERE created_at >= CURRENT_DATE - INTERVAL '30 days'\nGROUP BY DATE(created_at), event_type, provider, status\nORDER BY date DESC, event_count DESC;\n\nRAISE NOTICE 'Created oauth_statistics view';\n\n-- ============================================================================\n-- STEP 12: Add Comments for Documentation\n-- ============================================================================\n\nCOMMENT ON TABLE oauth_sessions IS 'Stores OAuth provider sessions and tokens for users';\nCOMMENT ON COLUMN oauth_sessions.provider IS 'OAuth provider: google, github, firebase';\nCOMMENT ON COLUMN oauth_sessions.provider_account_id IS 'User ID from the OAuth provider';\nCOMMENT ON COLUMN oauth_sessions.access_token IS 'OAuth access token (should be encrypted in production)';\nCOMMENT ON COLUMN oauth_sessions.refresh_token IS 'OAuth refresh token (should be encrypted in production)';\nCOMMENT ON COLUMN oauth_sessions.token_expires_at IS 'When the access token expires';\n\nCOMMENT ON TABLE oauth_audit_logs IS 'Audit trail for all OAuth authentication events';\nCOMMENT ON COLUMN oauth_audit_logs.event_type IS 'Type of OAuth event: login, signup, token_refresh, logout, error';\nCOMMENT ON COLUMN oauth_audit_logs.status IS 'Event status: success or failure';\nCOMMENT ON COLUMN oauth_audit_logs.metadata IS 'Additional context stored as JSON';\n\nCOMMENT ON FUNCTION find_or_create_oauth_user(VARCHAR, VARCHAR, VARCHAR, VARCHAR, TEXT) IS \n'Finds existing user by OAuth provider+UID or email, or creates new user. Returns user_id and is_new flag.';\n\nCOMMENT ON FUNCTION store_oauth_session(UUID, VARCHAR, VARCHAR, TEXT, TEXT, TIMESTAMP, TEXT, TEXT) IS \n'Stores or updates OAuth session for a user. Handles token storage and expiration tracking.';\n\nCOMMENT ON FUNCTION log_oauth_event(UUID, VARCHAR, VARCHAR, VARCHAR, TEXT, INET, TEXT, JSONB) IS \n'Logs OAuth authentication events for audit trail and debugging.';\n\nRAISE NOTICE 'Added documentation comments';\n\n-- ============================================================================\n-- STEP 13: Verify Migration Success\n-- ============================================================================\n\nDO $$\nDECLARE\n    v_users_count INT;\n    v_oauth_sessions_count INT;\n    v_oauth_audit_count INT;\nBEGIN\n    SELECT COUNT(*) INTO v_users_count FROM users;\n    SELECT COUNT(*) INTO v_oauth_sessions_count FROM oauth_sessions;\n    SELECT COUNT(*) INTO v_oauth_audit_count FROM oauth_audit_logs;\n    \n    RAISE NOTICE '✅ Migration completed successfully!';\n    RAISE NOTICE 'Users table: % rows', v_users_count;\n    RAISE NOTICE 'OAuth sessions table: % rows', v_oauth_sessions_count;\n    RAISE NOTICE 'OAuth audit logs table: % rows', v_oauth_audit_count;\nEND $$;\n\nCOMMIT;\n\n-- ============================================================================\n-- MIGRATION COMPLETE\n-- ============================================================================\n-- \n-- Summary of changes:\n-- 1. ✅ Added OAuth columns to users table (avatar_url, oauth_provider, oauth_uid, last_login)\n-- 2. ✅ Made password_hash nullable for OAuth users\n-- 3. ✅ Created oauth_sessions table for token management\n-- 4. ✅ Created oauth_audit_logs table for event tracking\n-- 5. ✅ Added indexes for OAuth lookups\n-- 6. ✅ Created functions for OAuth user management\n-- 7. ✅ Created views for analytics and monitoring\n--\n-- Next steps:\n-- 1. Update your backend to use find_or_create_oauth_user() function\n-- 2. Call store_oauth_session() after successful OAuth authentication\n-- 3. Call log_oauth_event() for audit trail\n-- 4. Monitor oauth_audit_logs for authentication issues\n--\n-- ============================================================================\n